// Independent data-only protocol port; reference: keiyoushi/extensions-source (Apache-2.0),
// commit dbf6c05d6a9520c60533f1626616263522bbe71a, Miaoqu.kt and MCCMSWeb.kt.
// The website search currently returns HTTP 404, so search is intentionally NOT exported.
var BASE = 'https://www.miaoqumh.org';
var endPages = {};
function fail(message) { throw new Error('喵趣漫画：' + message); }
// Ignore inert site-wide scripts/comments: Cloudflare jsd can coexist with public content.
async function verificationWall(body) {
  var rendered = String(body || '').replace(/<!--[\s\S]*?-->/g, '').replace(/<(script|style|template)\b[^>]*>[\s\S]*?<\/\1\s*>/gi, '');
  var rows = await triomi.select(rendered, 'title, h1, h2, h3, form#challenge-form, #challenge-running, #cf-challenge-running, #cf-challenge-stage', {text:{selector:'.'},id:{selector:'.',attr:'id'}});
  for (var i = 0; i < rows.length; i++) {
    if (/^(?:challenge-form|challenge-running|cf-challenge-running|cf-challenge-stage)$/.test(rows[i].id || '') || /^(?:Just a moment|Attention Required|人机验证|安全验证|Verify (?:you are|that you are) human|Checking your browser|Captcha(?:\s|$))/i.test((rows[i].text || '').trim())) return true;
  }
  return false;
}
async function pageHtml(url, reader) {
  var response = await triomi.fetch(url);
  if (response.status !== 200 && !(reader && response.status === 500)) fail('网站 HTTP ' + response.status);
  var body = response.body || '';
  if (await verificationWall(body)) fail('网站要求验证，无法直接读取');
  return body;
}
async function value(body, selector, attr) {
  var rows = await triomi.select(body, selector, {v:{selector:'.',attr:attr || 'text'}});
  return rows.length ? String(rows[0].v || '').trim() : '';
}
function mangaId(url) {
  var match = /^https:\/\/www\.miaoqumh\.org\/([A-Za-z0-9_-]+)\/?$/.exec(url || '');
  if (!match) fail('无效的漫画地址');
  return match[1];
}
async function discover(url, page) {
  var match = /^https:\/\/www\.miaoqumh\.org\/category\/order\/(hits|addtime)\/page\/([0-9]+)$/.exec(url || '');
  if (!match) fail('无效的浏览地址');
  page = Number(page) || 1;
  if (page < 1 || Math.floor(page) !== page || Number(match[2]) !== page) fail('页码无效');
  var key = match[1];
  if (endPages[key] && page > endPages[key]) return [];
  var body = await pageHtml(url, false);
  var next = await value(body, '#next', 'href');
  var nextPage = /\/page\/([0-9]+)\/?$/.exec(next);
  // The last page's Next points back to itself; never emit duplicate books indefinitely.
  if (nextPage && Number(nextPage[1]) < page) return [];
  if (!nextPage || Number(nextPage[1]) <= page) endPages[key] = page;
  var rows = await triomi.select(body, '#mangawrap > li', {
    title:{selector:'.manga-name',attr:'title'},text:'.manga-name',
    url:{selector:'a.manga-img',attr:'href',absolute:true},
    coverStyle:{selector:'a.manga-img',attr:'style'},author:'.manga-author'
  }, url);
  if (!rows.length && !/暂无|没有找到|未找到/.test(body)) fail('无法识别漫画列表');
  var items = [], seen = {};
  for (var i = 0; i < rows.length; i++) {
    var row = rows[i], id = mangaId(row.url), title = row.title || row.text;
    if (!title) fail('漫画标题缺失');
    if (seen[id]) continue;
    seen[id] = true;
    var cover = /background\s*:\s*url\(\s*['"]?([^'"\)]+)['"]?\s*\)/i.exec(row.coverStyle || '');
    var coverUrl = cover ? cover[1].trim() : '';
    if (coverUrl.indexOf('//') === 0) coverUrl = 'https:' + coverUrl;
    else if (coverUrl.indexOf('/') === 0) coverUrl = BASE + coverUrl;
    items.push({remoteId:id,title:title,url:row.url,coverUrl:coverUrl,author:row.author || ''});
  }
  return items;
}
async function detail(url, snapshot) {
  var id = mangaId(url), body = await pageHtml(url, false);
  var title = await value(body, '.manga-title h1.title-font');
  if (!title) fail('无法识别漫画详情');
  var chapters = [], seen = {};
  var sections = [{selector:'#episodes .epsbox a.epsbox-eplink',name:'连载'},
    {selector:'#extra_episodes .epsbox a.epsbox-eplink',name:'番外'}];
  for (var g = 0; g < sections.length; g++) {
    var raw = await triomi.select(body, sections[g].selector, {
      title:{selector:'.',attr:'title'},text:{selector:'.'},url:{selector:'.',attr:'href',absolute:true}
    }, url);
    // The current public desktop DOM is already oldest-first. Do not sort by numeric ID.
    for (var i = 0; i < raw.length; i++) {
      var row = raw[i], match = /^https:\/\/www\.miaoqumh\.org\/([0-9]+)\/([0-9]+)\.html$/.exec(row.url || '');
      if (!match) fail('章节地址无效');
      var remoteId = match[1] + '/' + match[2];
      if (seen[remoteId]) continue;
      seen[remoteId] = true;
      var name = row.title || (row.text || '').replace(/^\s*[0-9]+\s*[.、]\s*/, '');
      if (name.indexOf(title + ':') === 0) name = name.substring(title.length + 1);
      name = name.trim();
      if (!name) fail('章节标题缺失');
      chapters.push({remoteId:remoteId,title:name,url:row.url,volumeTitle:sections[g].name,locked:false});
    }
  }
  if (!chapters.length) fail('章节目录缺失');
  var statusText = await value(body, '.manga-episodes_text');
  return {item:{remoteId:id,title:title,url:url,coverUrl:await value(body,'.manga-img img','src'),
    author:await value(body,'.manga-author a.author'),description:await value(body,'p.manga-desc-font'),
    status:/完结|完結/.test(statusText)?'completed':(/连载|連載/.test(statusText)?'ongoing':'unknown')},chapters:chapters};
}
function base64Bytes(text) {
  text = String(text || '').replace(/\s/g, '');
  if (!text || text.length % 4 !== 0 || !/^(?:[A-Za-z0-9+/]{4})*(?:[A-Za-z0-9+/]{2}==|[A-Za-z0-9+/]{3}=)?$/.test(text)) fail('图片数据 Base64 无效');
  var alphabet = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/', out = [];
  for (var i = 0; i < text.length; i += 4) {
    var a = alphabet.indexOf(text.charAt(i)), b = alphabet.indexOf(text.charAt(i + 1));
    var c = alphabet.indexOf(text.charAt(i + 2)), d = alphabet.indexOf(text.charAt(i + 3));
    out.push((a << 2) | (b >> 4));
    if (text.charAt(i + 2) !== '=') out.push(((b & 15) << 4) | (c >> 2));
    if (text.charAt(i + 3) !== '=') out.push(((c & 3) << 6) | d);
  }
  return out;
}
function utf8(bytes) {
  var escaped = '';
  for (var i = 0; i < bytes.length; i++) escaped += '%' + ('0' + bytes[i].toString(16)).slice(-2);
  try {return decodeURIComponent(escaped);} catch (error) {fail('图片数据 UTF-8 无效');}
}
async function content(url, chapter) {
  var match = /^https:\/\/www\.miaoqumh\.org\/([0-9]+)\/([0-9]+)\.html$/.exec(url || '');
  if (!match) fail('章节地址无效');
  var body = await pageHtml(url, true);
  var encoded = /var\s+DATA\s*=\s*'([^']+)'/.exec(body);
  if (!encoded) fail('章节未提供公开图片数据；可能已下架或需要验证');
  var keys = ['8-bXd9iN','8-RXyjry','8-oYvwVy','8-4ZY57U','8-mbJpU7','8-6MM2Ei','8-54TiQr','8-Ph5xx9','8-bYgePR','8-Z9A3bW'];
  var key = keys[Number(match[2].slice(-1))], bytes = base64Bytes(encoded[1]), inner = '';
  for (var i = 0; i < bytes.length; i++) inner += String.fromCharCode(bytes[i] ^ key.charCodeAt(i & 7));
  var rows;
  try {rows = JSON.parse(utf8(base64Bytes(inner)));} catch (error) {fail('图片数据无法解析');}
  if (!Array.isArray(rows) || !rows.length) fail('章节图片列表为空');
  var images = [];
  for (var j = 0; j < rows.length; j++) {
    var image = rows[j] && rows[j].url;
    if (typeof image !== 'string' || !/^https?:\/\//.test(image) || /[\x00-\x20]/.test(image)) fail('章节图片地址无效');
    images.push(image);
  }
  return {images:images};
}
